from sys import stdin

def expected_time_to_set_record(n, r, m, tricks):
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    for t, p, d in tricks:
        new_dp = dp.copy()
        for i in range(t, n + 1):
            if dp[i-t] != float('inf'):
                new_dp[i] = min(new_dp[i], dp[i-t] + (i-t)*p + d*(1-p))
        dp = new_dp

    return min(dp[n] + (n-r)*(1-dp[n]/n), n)

def main():
    stdin.readline()  # discard the first line
    tricks = []
    for _ in range(int(stdin.readline().strip())):
        t, p, d = map(float, stdin.readline().strip().split())
        tricks.append((int(t), p, int(d)))

    n, r = map(int, stdin.readline().strip().split())

    result = expected_time_to_set_record(n, r, len(tricks), tricks)
    print(result)

if __name__ == "__main__":
    main()
